// Extract application details from Gmail data
const emailData = $input.item.json;

// Extract basic email information
const subject = emailData.Subject || emailData.subject || '';
const body = emailData.snippet || emailData.body || '';
const originalTo = emailData.To || emailData.to || '';

// Safer date parsing with error handling
let dateReceived;
try {
  // Gmail's internalDate is in milliseconds since epoch
  if (emailData.internalDate) {
    // Convert string to number if needed
    const timestamp = typeof emailData.internalDate === 'string' ? 
      parseInt(emailData.internalDate, 10) : emailData.internalDate;
    dateReceived = new Date(timestamp);
  } else if (emailData.date) {
    dateReceived = new Date(emailData.date);
  } else {
    // Fallback to current date if no date available
    dateReceived = new Date();
  }

  // Check if date is valid
  if (isNaN(dateReceived.getTime())) {
    console.log('Invalid date detected, using current date as fallback');
    dateReceived = new Date();
  }
} catch (error) {
  console.log('Error parsing date:', error.message, 'Using current date as fallback');
  dateReceived = new Date();
}

const today = new Date();

// Calculate days since application
const daysSince = Math.floor((today - dateReceived) / (1000 * 60 * 60 * 24));

// Extract company name from subject or body
let company = '';
const companyPatterns = [
  /(?:application|applied)\s+(?:to|at)\s+([A-Za-z0-9\s&.,'-]+?)(?:\s+for|\s+as|\s+-|$)/i,
  /([A-Za-z0-9\s&.,'-]+?)\s+(?:job|position|role|application)/i,
  /from:\s*([A-Za-z0-9\s&.,'-]+?)\s*</i
];

for (const pattern of companyPatterns) {
  const match = subject.match(pattern) || body.match(pattern);
  if (match && match[1]) {
    company = match[1].trim();
    break;
  }
}

// Extract position from subject or body
let position = '';
const positionPatterns = [
  /(?:for|as)\s+(?:a\s+)?([A-Za-z0-9\s&.,'-]+?)\s+(?:position|role|at|with)/i,
  /position:\s*([A-Za-z0-9\s&.,'-]+)/i,
  /role:\s*([A-Za-z0-9\s&.,'-]+)/i,
  /([A-Za-z0-9\s&.,'-]+?)\s+(?:developer|engineer|manager|analyst|specialist|coordinator)/i
];

for (const pattern of positionPatterns) {
  const match = subject.match(pattern) || body.match(pattern);
  if (match && match[1]) {
    position = match[1].trim();
    break;
  }
}

// Extract recipient email for follow-up
let recipientEmail = '';
if (originalTo) {
  // Extract email from "Name <email@domain.com>" format or just "email@domain.com"
  const emailMatch = originalTo.match(/<([^>]+)>/) || originalTo.match(/([\w.-]+@[\w.-]+\.[\w]+)/);
  if (emailMatch && emailMatch[1]) {
    recipientEmail = emailMatch[1].trim();
  } else {
    recipientEmail = originalTo.trim();
  }
}

// Determine if follow-up is needed based on timing and content
let needsFollowup = false;
const followupKeywords = ['follow up', 'follow-up', 'check in', 'status', 'update'];
const hasFollowupKeywords = followupKeywords.some(keyword => 
  subject.toLowerCase().includes(keyword) || body.toLowerCase().includes(keyword)
);

// Follow-up logic:
// - If 7-14 days since application and no recent follow-up keywords
// - If 21+ days since application
if ((daysSince >= 7 && daysSince <= 14 && !hasFollowupKeywords) || daysSince >= 21) {
  needsFollowup = true;
}

// Safe date formatting with error handling
let applicationDateString;
try {
  applicationDateString = dateReceived.toISOString().split('T')[0];
} catch (error) {
  console.log('Error formatting date:', error.message);
  applicationDateString = new Date().toISOString().split('T')[0];
}

// Return structured data
return {
  json: {
    company: company || 'Unknown Company',
    position: position || 'Unknown Position',
    daysSince: daysSince,
    needsFollowup: needsFollowup,
    originalSubject: subject,
    originalTo: originalTo,
    recipientEmail: recipientEmail,
    applicationDate: applicationDateString,
    emailId: emailData.id || emailData.messageId
  }
};
